import os, base64, zlib
R = "LockCOC" if os.path.isdir("LockCOC") else "."
def P(p): return os.path.join(R, p)
def rd(p): return open(P(p), encoding="utf-8").read()
def w(p, s): open(P(p), "w", encoding="utf-8").write(s)
F = {'filters.js': '', 'filters.css': ''}
def D(k): return zlib.decompress(base64.b64decode(F[k])).decode("utf-8")
def sub(s, old, new, what):
    if old not in s: raise SystemExit("[loi] khong thay doan can sua: " + what)
    return s.replace(old, new, 1)
if os.path.exists(P("static/js/filters.js")): raise SystemExit("[loi] da ap dung patch36 roi")
if not os.path.exists(P("static/js/cam28.js")): raise SystemExit("[loi] can cai patch31 truoc")
w("static/js/filters.js", D("filters.js"))
w("static/polish.css", rd("static/polish.css") + "\n" + D("filters.css"))
h = rd("templates/index.html")
h = sub(h, '  <script src="/static/js/cam28.js"></script>', '  <script src="/static/js/cam28.js"></script>\n  <script src="/static/js/filters.js"></script>', "index script")
w("templates/index.html", h)
L = rd("templates/landing.html")
card = '        <article class="feat-new"><svg class="ic xl"><use href="#i-star"/></svg><h3>Filter Locket <em class="nw">Mới</em></h3><p>16 filter gắn lên khuôn mặt: tóc, râu, tai mèo, vương miện, tim bay, tiền… và hiệu ứng Slimed chảy nhớt xanh. Kéo để chỉnh, chụp là in luôn vào ảnh và video.</p></article>\n'
L = sub(L, '        <article class="feat-new"><svg class="ic xl"><use href="#i-camera"/></svg><h3>Chụp Đêm', card + '        <article class="feat-new"><svg class="ic xl"><use href="#i-camera"/></svg><h3>Chụp Đêm', "card")
L = sub(L, 'Camera mới</b><span>Đêm, Liên tiếp, Boomerang, Photobooth</span>', 'Camera mới</b><span>Filter, Đêm, Liên tiếp, Boomerang</span>', "facts") if "Camera mới</b><span>Đêm, Liên tiếp, Boomerang, Photobooth" in L else L
w("templates/landing.html", L)
fj = P("static/js/fold.js")
if os.path.exists(fj):
    f = rd("static/js/fold.js")
    if "Filter Locket" not in f: f = f.replace("(Chat kiểu mới|", "(Filter Locket|Chat kiểu mới|", 1)
    w("static/js/fold.js", f)
print("[ok] patch36 xong: Filter Locket")
